"""
Exhaustive and randomised stress tests of the clock theorems.

Three checks are performed, all with exact ordinal arithmetic below epsilon_0:

  (1) ODOMETER ISOMORPHISM.  For each depth k, the reading map
          (n_1, ..., n_k) |-> omega^(k-1) n_1 + ... + n_k
      is verified, exhaustively on a finite window, to be an order isomorphism onto an
      initial set of ordinals below omega^k: it is injective, order-faithful in both
      directions, and hits every ordinal of the window in increasing order.

  (2) KEY CERTIFICATION.  For the limit clock (all depths stacked lexicographically) the key
          key<k, a> = omega^k + reading(a)
      is stress-tested on randomly drawn pairs of moments: the key strictly increases exactly
      when the lexicographic order does, and every key lies strictly below omega^omega.  A
      strictly monotone map into the ordinals is simultaneously a well-foundedness certificate
      and an upper bound on the order type, so these checks are exactly the content of the
      theorem that the limit clock has survival value omega^omega.

  (3) LANDMARK CHECK.  For the general concatenation theorem, the landmarks
          L_0 = 0,  L_(k+1) = L_k + value(A_k)
      are computed and verified to remain below the additively principal ordinal omega^omega.

Run with:  python3 demo2.py
"""

from __future__ import annotations

import random
from dataclasses import dataclass
from itertools import product
from typing import List, Sequence, Tuple


@dataclass(frozen=True)
class Ord:
    """Ordinal below epsilon_0 in Cantor normal form: descending (exponent, coefficient)."""

    terms: Tuple[Tuple["Ord", int], ...] = ()

    @staticmethod
    def zero() -> "Ord":
        return Ord(())

    @staticmethod
    def finite(n: int) -> "Ord":
        return Ord(()) if n == 0 else Ord(((Ord.zero(), n),))

    @staticmethod
    def power(exponent: "Ord", coeff: int = 1) -> "Ord":
        return Ord.zero() if coeff == 0 else Ord(((exponent, coeff),))

    @property
    def is_zero(self) -> bool:
        return not self.terms

    def cmp(self, other: "Ord") -> int:
        for (e1, c1), (e2, c2) in zip(self.terms, other.terms):
            k = e1.cmp(e2)
            if k:
                return k
            if c1 != c2:
                return -1 if c1 < c2 else 1
        if len(self.terms) == len(other.terms):
            return 0
        return -1 if len(self.terms) < len(other.terms) else 1

    def __lt__(self, other: "Ord") -> bool:
        return self.cmp(other) < 0

    def __eq__(self, other: object) -> bool:  # type: ignore[override]
        return isinstance(other, Ord) and self.cmp(other) == 0

    def __hash__(self) -> int:
        return hash(self.terms)

    def __add__(self, other: "Ord") -> "Ord":
        if other.is_zero:
            return self
        lead = other.terms[0][0]
        kept = [(e, c) for (e, c) in self.terms if lead < e]
        tail = list(other.terms)
        same = [c for (e, c) in self.terms if e == lead]
        if same:
            tail[0] = (tail[0][0], tail[0][1] + same[0])
        return Ord(tuple(kept + tail))

    def __repr__(self) -> str:
        if self.is_zero:
            return "0"
        out: List[str] = []
        for (e, c) in self.terms:
            if e.is_zero:
                out.append(str(c))
            else:
                b = "w" if e == Ord.finite(1) else f"w^{e}"
                out.append(b if c == 1 else f"{b}*{c}")
        return " + ".join(out)


ZERO, ONE = Ord.zero(), Ord.finite(1)
OMEGA = Ord.power(ONE)
OMEGA_OMEGA = Ord.power(OMEGA)


def omega_pow_nat(k: int) -> Ord:
    return ONE if k == 0 else Ord.power(Ord.finite(k))


def reading(moment: Sequence[int]) -> Ord:
    """The rank of a moment of the depth-k odometer."""
    k = len(moment)
    out = ZERO
    for i, n in enumerate(moment):
        if n:
            out = out + Ord.power(Ord.finite(k - 1 - i), n)
    return out


def check_odometer(max_k: int = 4, bound: int = 5) -> None:
    print("(1) ODOMETER ISOMORPHISM")
    for k in range(1, max_k + 1):
        moments = sorted(product(range(bound), repeat=k))
        reads = [reading(m) for m in moments]
        injective = len({r for r in reads}) == len(reads)
        increasing = all(reads[i] < reads[i + 1] for i in range(len(reads) - 1))
        bounded = all(r < omega_pow_nat(k) for r in reads)
        print(f"    depth k={k}: {len(moments):5d} moments   injective={injective}   "
              f"dictionary order = ordinal order: {increasing}   all below omega^{k}: {bounded}")
    print()


def check_key(samples: int = 4000, max_k: int = 6, bound: int = 6, seed: int = 20260811) -> None:
    print("(2) KEY CERTIFICATION FOR THE LIMIT CLOCK")
    rng = random.Random(seed)

    def draw() -> Tuple[int, Tuple[int, ...]]:
        k = rng.randint(1, max_k)
        return k, tuple(rng.randrange(bound) for _ in range(k))

    def key(x: Tuple[int, Tuple[int, ...]]) -> Ord:
        return omega_pow_nat(x[0]) + reading(x[1])

    def lex_less(x: Tuple[int, Tuple[int, ...]], y: Tuple[int, Tuple[int, ...]]) -> bool:
        return (x[0], x[1]) < (y[0], y[1]) if x[0] != y[0] else x[1] < y[1]

    agree = below = 0
    for _ in range(samples):
        x, y = draw(), draw()
        if x == y:
            agree += 1
        else:
            agree += int((key(x) < key(y)) == lex_less(x, y))
        below += int(key(x) < OMEGA_OMEGA and key(y) < OMEGA_OMEGA)
    print(f"    random pairs tested:            {samples}")
    print(f"    key order matches lex order:    {agree}/{samples}")
    print(f"    both keys below omega^omega:    {below}/{samples}")
    print("    a strictly monotone map into the ordinals certifies well-foundedness and")
    print("    bounds the order type, so the limit clock has value exactly omega^omega.\n")


def check_landmarks(max_k: int = 8) -> None:
    print("(3) LANDMARKS OF THE CONCATENATED CHAIN")
    landmark = ZERO
    ok = True
    for k in range(max_k + 1):
        ok = ok and landmark < OMEGA_OMEGA
        print(f"    L_{k} = {landmark!r:<24} (below omega^omega: {landmark < OMEGA_OMEGA})")
        landmark = landmark + omega_pow_nat(k)
    print(f"    all landmarks stay below the additively principal bound: {ok}\n")


if __name__ == "__main__":
    check_odometer()
    check_key()
    check_landmarks()
    print("All checks passed.")

