"""Algorithm A — Exact Cantor normal form arithmetic for ordinals below epsilon_0."""

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Tuple


@dataclass(frozen=True)
class Ord:
    """omega^e_1 * c_1 + ... + omega^e_m * c_m with e_1 > ... > e_m and c_i >= 1."""

    terms: Tuple[Tuple["Ord", int], ...] = ()

    @staticmethod
    def zero() -> "Ord":
        return Ord(())

    @staticmethod
    def finite(n: int) -> "Ord":
        if n < 0:
            raise ValueError("ordinals are non-negative")
        return Ord(()) if n == 0 else Ord(((Ord.zero(), n),))

    @staticmethod
    def power(exponent: "Ord", coeff: int = 1) -> "Ord":
        return Ord.zero() if coeff == 0 else Ord(((exponent, coeff),))

    @property
    def is_zero(self) -> bool:
        return not self.terms

    def compare(self, other: "Ord") -> int:
        """-1, 0, +1 according as self <, =, > other.  O(#terms) up to recursion."""
        for (e1, c1), (e2, c2) in zip(self.terms, other.terms):
            k = e1.compare(e2)
            if k:
                return k
            if c1 != c2:
                return -1 if c1 < c2 else 1
        if len(self.terms) == len(other.terms):
            return 0
        return -1 if len(self.terms) < len(other.terms) else 1

    def __lt__(self, other: "Ord") -> bool:
        return self.compare(other) < 0

    def __le__(self, other: "Ord") -> bool:
        return self.compare(other) <= 0

    def __eq__(self, other: object) -> bool:  # type: ignore[override]
        return isinstance(other, Ord) and self.compare(other) == 0

    def __hash__(self) -> int:
        return hash(self.terms)

    def __add__(self, other: "Ord") -> "Ord":
        """Ordinal addition: terms of the left factor below the leading exponent of the
        right factor are absorbed.  This is left absorption made concrete."""
        if other.is_zero:
            return self
        lead = other.terms[0][0]
        kept: List[Tuple[Ord, int]] = [(e, c) for (e, c) in self.terms if lead < e]
        tail: List[Tuple[Ord, int]] = list(other.terms)
        same = [c for (e, c) in self.terms if e == lead]
        if same:
            tail[0] = (tail[0][0], tail[0][1] + same[0])
        return Ord(tuple(kept + tail))

    def __mul__(self, other: "Ord") -> "Ord":
        """Ordinal multiplication self * other, distributing over the right factor."""
        if self.is_zero or other.is_zero:
            return Ord.zero()
        lead_e, lead_c = self.terms[0]
        out = Ord.zero()
        for (e, c) in other.terms:
            if e.is_zero:
                out = out + Ord.power(lead_e, lead_c * c) + Ord(self.terms[1:])
            else:
                out = out + Ord.power(lead_e + e, c)
        return out

    def __repr__(self) -> str:
        if self.is_zero:
            return "0"
        out: List[str] = []
        for (e, c) in self.terms:
            if e.is_zero:
                out.append(str(c))
            else:
                if e == Ord.finite(1):
                    base = "w"
                elif len(e.terms) == 1 and e.terms[0][0].is_zero:
                    base = f"w^{e}"
                else:
                    base = f"w^({e})"
                out.append(base if c == 1 else f"{base}*{c}")
        return " + ".join(out)


if __name__ == "__main__":
    ZERO, ONE = Ord.zero(), Ord.finite(1)
    OMEGA = Ord.power(ONE)
    print("1 + w      =", ONE + OMEGA, "   (left absorption)")
    print("w + 1      =", OMEGA + ONE)
    print("w * w      =", OMEGA * OMEGA)
    print("w * w^w    =", OMEGA * Ord.power(OMEGA), "  (a fixed point of refinement)")
    print("w^3 < w^4  :", Ord.power(Ord.finite(3)) < Ord.power(Ord.finite(4)))

"""Algorithm B — The odometer reading map and its inverse (base-omega positional notation).

A moment of the depth-k clock is a k-tuple of naturals in dictionary order; its rank is the
base-omega numeral it spells.  Decoding inverts this using uniqueness of the Cantor normal
form.  Both directions are O(k).
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

# an ordinal below omega^omega is stored sparsely as {exponent: coefficient}
Ordinal = Dict[int, int]


def reading(moment: Sequence[int]) -> Ordinal:
    """(n_1, ..., n_k) |-> omega^(k-1) n_1 + ... + omega n_(k-1) + n_k."""
    k = len(moment)
    out: Ordinal = {}
    for i, n in enumerate(moment):
        if n:
            out[k - 1 - i] = n
    return out


def decode(value: Ordinal, k: int) -> Tuple[int, ...]:
    """Inverse of `reading` at depth k; requires every exponent to be < k."""
    if any(e >= k for e in value):
        raise ValueError("ordinal does not fit on a depth-k odometer")
    return tuple(value.get(k - 1 - i, 0) for i in range(k))


def compare(a: Ordinal, b: Ordinal) -> int:
    """Compare two base-omega numerals: leading exponents first, then coefficients."""
    for e in sorted(set(a) | set(b), reverse=True):
        ca, cb = a.get(e, 0), b.get(e, 0)
        if ca != cb:
            return -1 if ca < cb else 1
    return 0


def show(value: Ordinal) -> str:
    if not value:
        return "0"
    parts: List[str] = []
    for e in sorted(value, reverse=True):
        c = value[e]
        if e == 0:
            parts.append(str(c))
        else:
            base = "w" if e == 1 else f"w^{e}"
            parts.append(base if c == 1 else f"{base}*{c}")
    return " + ".join(parts)


def tick(moment: Sequence[int]) -> Tuple[int, ...]:
    """The immediate successor moment: increment the least significant digit."""
    out = list(moment)
    out[-1] += 1
    return tuple(out)


if __name__ == "__main__":
    m = (4, 3, 2)
    r = reading(m)
    print("moment", m, "reads", show(r), "and decodes back to", decode(r, 3))
    print("successor of", m, "is", tick(m), "reading", show(reading(tick(m))))
    print("dictionary order matches ordinal order:",
          all(compare(reading(a), reading(b)) == (-1 if a < b else 0 if a == b else 1)
              for a in [(0, 0, 0), (0, 1, 5), (2, 0, 0), (2, 0, 1)]
              for b in [(0, 0, 0), (0, 1, 5), (2, 0, 0), (2, 0, 1)]))

"""Algorithm C — Key evaluation and monotonicity certification for lexicographic sums.

Given a chain of lives A_0, A_1, ... played one after another, the landmark key

    key<k, a> = L_k + rank_{A_k}(a),      L_0 = 0,  L_(k+1) = L_k + value(A_k),

is strictly increasing for the lexicographic order on the dependent sum.  A strictly
monotone map into the ordinals is at once (i) a well-foundedness certificate, (ii) an upper
bound on the order type, and (iii) an executable comparison procedure.  For the limit clock
(A_k the depth-k odometer, value omega^k) the landmarks are L_k = omega^(k-1), and the key
specialises to omega^k + rank(a).
"""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

Ordinal = Dict[int, int]          # exponent -> coefficient, for ordinals below omega^omega
Moment = Tuple[int, Tuple[int, ...]]   # <depth k, a k-tuple digit string>


def add(a: Ordinal, b: Ordinal) -> Ordinal:
    """Ordinal addition on base-omega numerals (left absorption below b's leading exponent)."""
    if not b:
        return dict(a)
    lead = max(b)
    out = {e: c for e, c in a.items() if e > lead}
    for e, c in b.items():
        out[e] = out.get(e, 0) + c
    if lead in a:
        out[lead] = a[lead] + b[lead]
    return {e: c for e, c in out.items() if c}


def compare(a: Ordinal, b: Ordinal) -> int:
    for e in sorted(set(a) | set(b), reverse=True):
        ca, cb = a.get(e, 0), b.get(e, 0)
        if ca != cb:
            return -1 if ca < cb else 1
    return 0


def rank(digits: Sequence[int]) -> Ordinal:
    k = len(digits)
    return {k - 1 - i: n for i, n in enumerate(digits) if n}


def landmarks(values: Sequence[Ordinal]) -> List[Ordinal]:
    """L_0 = 0, L_(k+1) = L_k + value(A_k)."""
    out: List[Ordinal] = [{}]
    for v in values:
        out.append(add(out[-1], v))
    return out


def key(moment: Moment, marks: Sequence[Ordinal]) -> Ordinal:
    k, digits = moment
    return add(marks[k], rank(digits))


def lex_less(x: Moment, y: Moment) -> bool:
    return x[0] < y[0] if x[0] != y[0] else x[1] < y[1]


def certify(sample: Sequence[Moment], marks: Sequence[Ordinal], ceiling: int) -> bool:
    """Verify strict monotonicity on a sample, and that all keys lie below omega^ceiling."""
    for x in sample:
        if not all(e < ceiling for e in key(x, marks)):
            return False
        for y in sample:
            if x != y and (compare(key(x, marks), key(y, marks)) < 0) != lex_less(x, y):
                return False
    return True


if __name__ == "__main__":
    # the limit clock: A_k is the depth-k odometer, of value omega^k
    values: List[Ordinal] = [{k: 1} if k else {0: 1} for k in range(8)]
    marks = landmarks(values)
    print("landmarks:", [sorted(m.items()) for m in marks[:6]])
    sample: List[Moment] = [(k, tuple(range(k))) for k in range(1, 7)] + \
                           [(3, (0, 0, 0)), (3, (1, 2, 3)), (5, (0, 0, 0, 0, 1))]
    print("key of <3,(1,2,3)>:", sorted(key((3, (1, 2, 3)), marks).items(), reverse=True))
    print("certified strictly monotone and below omega^omega:",
          certify(sample, marks, ceiling=10 ** 6))

"""Algorithm D — Closed-form stage evaluation for the monotone transfinite machine.

The machine has one cell per moment of the omega^2-clock; cell (m, n) has arrival time
omega*m + n.  Its rule is: a cell switches on once all strictly earlier cells are on, with
the union of all earlier configurations taken at limit times.  Naively, evaluating the
configuration at time alpha requires a transfinite recursion through every beta < alpha.
The closed form

    cell x is on at time alpha   <=>   arrival(x) <= alpha

replaces that recursion by a single ordinal comparison, in O(1).  Decoding alpha + 1 back
into a cell produces, for every alpha < omega^2, an explicit witness that the stage has
changed — which is exactly the proof that no time below omega^2 is terminal.
"""

from __future__ import annotations

from typing import Iterator, Optional, Tuple

Cell = Tuple[int, int]                 # (m, n)  <->  arrival omega*m + n
Time = Optional[Tuple[int, int]]       # (m, n) means omega*m + n;  None means omega^2


def arrival(cell: Cell) -> Tuple[int, int]:
    return cell


def leq(a: Tuple[int, int], t: Time) -> bool:
    """Compare an arrival time with a machine time (None = omega^2, above everything)."""
    if t is None:
        return True
    return a[0] < t[0] or (a[0] == t[0] and a[1] <= t[1])


def is_on(cell: Cell, t: Time) -> bool:
    """Closed form of the stages."""
    return leq(arrival(cell), t)


def successor(t: Time) -> Time:
    return None if t is None else (t[0], t[1] + 1)


def decode(t: Tuple[int, int]) -> Cell:
    """The unique cell whose arrival time is the given ordinal below omega^2."""
    return t


def new_cell_at(t: Tuple[int, int]) -> Cell:
    """Witness that the stage changes between t and t+1: the cell arriving at t+1."""
    return decode((t[0], t[1] + 1))


def is_terminal(t: Time) -> bool:
    """A time is terminal when one more step adds no cell.  Only omega^2 qualifies."""
    if t is None:
        return True
    w = new_cell_at(t)
    return is_on(w, t)


def configuration(t: Time, rows: int, cols: int) -> Iterator[Tuple[Cell, bool]]:
    for m in range(rows):
        for n in range(cols):
            yield (m, n), is_on((m, n), t)


if __name__ == "__main__":
    for t in [(0, 0), (0, 7), (1, 0), (3, 2)]:
        print(f"time omega*{t[0]}+{t[1]}: terminal = {is_terminal(t)}, "
              f"new cell at next step = {new_cell_at(t)}")
    print("time omega^2: terminal =", is_terminal(None))
    print("closure ordinal = omega^2, the least terminal time.")
